mapper.select:
SELECT strategy_id strategyId, strategy_code strategyCode, strategy_name strategyName,
       create_by createBy, create_time createTime, update_by updateBy, update_time updateTime, remark
FROM sys_permission_strategy WHERE strategy_id=#{id}

SELECT DISTINCT m.perms FROM sys_menu m
JOIN (
  SELECT rm.menu_id FROM sys_role_menu rm JOIN (
    SELECT ur.role_id FROM sys_user_role ur JOIN sys_role r ON r.role_id=ur.role_id AND r.status='0' AND r.del_flag='0' WHERE ur.user_id=#{userId}
    UNION SELECT pr.role_id FROM sys_user_post up JOIN sys_post_role pr ON pr.post_id=up.post_id JOIN sys_role r ON r.role_id=pr.role_id AND r.status='0' AND r.del_flag='0' WHERE up.user_id=#{userId}
  ) er ON er.role_id=rm.role_id
  UNION
  SELECT sm.menu_id FROM sys_role_strategy rs JOIN sys_strategy_menu sm ON sm.strategy_id=rs.strategy_id JOIN (
    SELECT ur.role_id FROM sys_user_role ur JOIN sys_role r ON r.role_id=ur.role_id AND r.status='0' AND r.del_flag='0' WHERE ur.user_id=#{userId}
    UNION SELECT pr.role_id FROM sys_user_post up JOIN sys_post_role pr ON pr.post_id=up.post_id JOIN sys_role r ON r.role_id=pr.role_id AND r.status='0' AND r.del_flag='0' WHERE up.user_id=#{userId}
  ) er ON er.role_id=rs.role_id
  UNION SELECT gm.menu_id FROM sys_user_group ug JOIN sys_group_menu gm ON gm.group_id=ug.group_id WHERE ug.user_id=#{userId}
  UNION SELECT sm.menu_id FROM sys_user_group ug JOIN sys_group_strategy gs ON gs.group_id=ug.group_id JOIN sys_strategy_menu sm ON sm.strategy_id=gs.strategy_id WHERE ug.user_id=#{userId}
) effective ON effective.menu_id=m.menu_id
WHERE m.status='0' AND m.perms IS NOT NULL AND m.perms<>''

SELECT DISTINCT m.perms FROM sys_menu m JOIN (
  SELECT menu_id FROM sys_role_menu WHERE role_id=#{roleId}
  UNION SELECT sm.menu_id FROM sys_role_strategy rs JOIN sys_strategy_menu sm ON sm.strategy_id=rs.strategy_id WHERE rs.role_id=#{roleId}
) effective ON effective.menu_id=m.menu_id
WHERE m.status='0' AND m.perms IS NOT NULL AND m.perms<>''

SELECT DISTINCT menu_id FROM (
  SELECT rm.menu_id FROM sys_role_menu rm JOIN (
    SELECT ur.role_id FROM sys_user_role ur JOIN sys_role r ON r.role_id=ur.role_id AND r.status='0' AND r.del_flag='0' WHERE ur.user_id=#{userId}
    UNION SELECT pr.role_id FROM sys_user_post up JOIN sys_post_role pr ON pr.post_id=up.post_id JOIN sys_role r ON r.role_id=pr.role_id AND r.status='0' AND r.del_flag='0' WHERE up.user_id=#{userId}
  ) er ON er.role_id=rm.role_id
  UNION SELECT sm.menu_id FROM sys_role_strategy rs JOIN sys_strategy_menu sm ON sm.strategy_id=rs.strategy_id JOIN (
    SELECT ur.role_id FROM sys_user_role ur JOIN sys_role r ON r.role_id=ur.role_id AND r.status='0' AND r.del_flag='0' WHERE ur.user_id=#{userId}
    UNION SELECT pr.role_id FROM sys_user_post up JOIN sys_post_role pr ON pr.post_id=up.post_id JOIN sys_role r ON r.role_id=pr.role_id AND r.status='0' AND r.del_flag='0' WHERE up.user_id=#{userId}
  ) er ON er.role_id=rs.role_id
  UNION SELECT gm.menu_id FROM sys_user_group ug JOIN sys_group_menu gm ON gm.group_id=ug.group_id WHERE ug.user_id=#{userId}
  UNION SELECT sm.menu_id FROM sys_user_group ug JOIN sys_group_strategy gs ON gs.group_id=ug.group_id JOIN sys_strategy_menu sm ON sm.strategy_id=gs.strategy_id WHERE ug.user_id=#{userId}
) x ORDER BY menu_id

SELECT DISTINCT dr.scope_type
FROM sys_role_data_rule dr
JOIN sys_menu m ON m.menu_id=dr.menu_id
JOIN (
  SELECT ur.role_id FROM sys_user_role ur JOIN sys_role r ON r.role_id=ur.role_id AND r.status='0' AND r.del_flag='0' WHERE ur.user_id=#{userId}
  UNION SELECT pr.role_id FROM sys_user_post up JOIN sys_post_role pr ON pr.post_id=up.post_id JOIN sys_role r ON r.role_id=pr.role_id AND r.status='0' AND r.del_flag='0' WHERE up.user_id=#{userId}
) er ON er.role_id=dr.role_id
WHERE m.perms=#{permission}

SELECT DISTINCT user_id FROM (
  SELECT ur.user_id FROM sys_role_strategy rs JOIN sys_user_role ur ON ur.role_id=rs.role_id WHERE rs.strategy_id=#{strategyId}
  UNION SELECT up.user_id FROM sys_role_strategy rs JOIN sys_post_role pr ON pr.role_id=rs.role_id JOIN sys_user_post up ON up.post_id=pr.post_id WHERE rs.strategy_id=#{strategyId}
  UNION SELECT ug.user_id FROM sys_group_strategy gs JOIN sys_user_group ug ON ug.group_id=gs.group_id WHERE gs.strategy_id=#{strategyId}
) u

SELECT DISTINCT user_id FROM (
  SELECT user_id FROM sys_user_role WHERE role_id=#{roleId}
  UNION SELECT up.user_id FROM sys_post_role pr JOIN sys_user_post up ON up.post_id=pr.post_id WHERE pr.role_id=#{roleId}
) users

SELECT COUNT(*) FROM sys_role r JOIN (
  SELECT role_id FROM sys_user_role WHERE user_id=#{userId}
  UNION SELECT pr.role_id FROM sys_user_post up JOIN sys_post_role pr ON pr.post_id=up.post_id WHERE up.user_id=#{userId}
) er ON er.role_id=r.role_id
WHERE r.status='0' AND r.del_flag='0' AND r.hide_phone='Y'

SELECT file_id fileId,bucket,file_type fileType,file_hash fileHash,content_type contentType,
       storage_path storagePath,file_url fileUrl,file_size fileSize,create_by createBy,create_time createTime,remark
FROM sys_file

  AND bucket LIKE CONCAT('%',#{bucket},'%')
  AND file_type LIKE CONCAT('%',#{fileType},'%')
  AND file_hash LIKE CONCAT('%',#{fileHash},'%')
  AND content_type LIKE CONCAT('%',#{contentType},'%')
  AND file_size = #{fileSize}
  AND file_size >= #{minSize}
  AND file_size <= #{maxSize}
  AND create_time >= #{beginTime}
  AND create_time < DATE_ADD(#{endTime}, INTERVAL 1 DAY)
 ORDER BY file_id DESC

SELECT r.reference_id referenceId,r.file_id fileId,r.reference_name referenceName,r.reference_type referenceType,
       r.reference_target_id referenceTargetId,r.create_by createBy,r.create_time createTime,r.remark,
       f.file_url fileUrl,f.content_type contentType,f.file_size fileSize
FROM sys_file_reference r JOIN sys_file f ON f.file_id=r.file_id

  AND r.file_id=#{fileId}
  AND r.reference_name LIKE CONCAT('%',#{referenceName},'%')
  AND r.reference_type=#{referenceType}
  AND r.reference_target_id=#{referenceTargetId}
  AND r.create_time >= #{beginTime}
  AND r.create_time < DATE_ADD(#{endTime}, INTERVAL 1 DAY)
 ORDER BY r.reference_id DESC
